-- Room version 11
CREATE TABLE IF NOT EXISTS `grocery_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `quantity` INTEGER NOT NULL, `price` REAL NOT NULL, `category` TEXT NOT NULL, `expiryDate` INTEGER, `threshold` INTEGER NOT NULL, `purchasedDate` INTEGER NOT NULL, `subcategory` TEXT, `userId` TEXT NOT NULL, `householdId` TEXT, FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_grocery_items_userId` ON `grocery_items` (`userId`);
CREATE INDEX IF NOT EXISTS `index_grocery_items_householdId` ON `grocery_items` (`householdId`);
CREATE TABLE IF NOT EXISTS `budget_entries` (`monthYear` TEXT NOT NULL, `limitAmount` REAL NOT NULL, `userId` TEXT NOT NULL, `householdId` TEXT, `scopeKey` TEXT NOT NULL, PRIMARY KEY(`scopeKey`, `monthYear`), FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_budget_entries_userId` ON `budget_entries` (`userId`);
CREATE INDEX IF NOT EXISTS `index_budget_entries_householdId` ON `budget_entries` (`householdId`);
CREATE TABLE IF NOT EXISTS `inventory_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `itemId` INTEGER, `itemName` TEXT NOT NULL, `category` TEXT NOT NULL, `changeType` TEXT NOT NULL, `amountChanged` INTEGER NOT NULL, `unitPriceAtChange` REAL NOT NULL, `timestamp` INTEGER NOT NULL, `userId` TEXT NOT NULL, `householdId` TEXT, FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`itemId`) REFERENCES `grocery_items`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS `index_inventory_logs_userId` ON `inventory_logs` (`userId`);
CREATE INDEX IF NOT EXISTS `index_inventory_logs_householdId` ON `inventory_logs` (`householdId`);
CREATE INDEX IF NOT EXISTS `index_inventory_logs_itemId` ON `inventory_logs` (`itemId`);
CREATE INDEX IF NOT EXISTS `index_inventory_logs_timestamp` ON `inventory_logs` (`timestamp`);
CREATE INDEX IF NOT EXISTS `index_inventory_logs_changeType` ON `inventory_logs` (`changeType`);
CREATE TABLE IF NOT EXISTS `shopping_list_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sourceItemId` INTEGER, `itemName` TEXT NOT NULL, `category` TEXT NOT NULL, `quantityNeeded` INTEGER NOT NULL, `quantityLabel` TEXT NOT NULL DEFAULT '', `estimatedUnitPrice` REAL NOT NULL, `addedBy` TEXT NOT NULL DEFAULT 'Auto', `assignedTo` TEXT NOT NULL DEFAULT 'Household', `isChecked` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `subcategory` TEXT, `userId` TEXT NOT NULL, `householdId` TEXT, FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_shopping_list_items_userId` ON `shopping_list_items` (`userId`);
CREATE INDEX IF NOT EXISTS `index_shopping_list_items_householdId` ON `shopping_list_items` (`householdId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_shopping_list_items_sourceItemId` ON `shopping_list_items` (`sourceItemId`);
CREATE TABLE IF NOT EXISTS `checklist_history` (`id` TEXT NOT NULL, `dishName` TEXT NOT NULL, `servings` INTEGER NOT NULL, `status` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `missingChecklistJson` TEXT NOT NULL, `inventoryDeductedJson` TEXT NOT NULL, `addedShoppingKeysJson` TEXT NOT NULL, `stateJson` TEXT NOT NULL DEFAULT '', `userId` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_checklist_history_userId` ON `checklist_history` (`userId`);
CREATE TABLE IF NOT EXISTS `users` (`userId` TEXT NOT NULL, `email` TEXT NOT NULL, `displayName` TEXT NOT NULL, `passwordHash` TEXT NOT NULL, `passwordSalt` TEXT NOT NULL, `passwordIterations` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`userId`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_users_email` ON `users` (`email`);
CREATE TABLE IF NOT EXISTS `households` (`householdId` TEXT NOT NULL, `name` TEXT NOT NULL, `joinCode` TEXT NOT NULL, `description` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`householdId`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_households_joinCode` ON `households` (`joinCode`);
CREATE TABLE IF NOT EXISTS `household_members` (`householdId` TEXT NOT NULL, `userId` TEXT NOT NULL, `role` TEXT NOT NULL DEFAULT 'Member', `status` TEXT NOT NULL DEFAULT 'Active', `lastSeenAt` INTEGER, PRIMARY KEY(`householdId`, `userId`), FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_household_members_userId` ON `household_members` (`userId`);
CREATE TABLE IF NOT EXISTS `local_session` (`id` INTEGER NOT NULL, `userId` TEXT, `householdId` TEXT, `activeHouseholdId` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`userId`) REFERENCES `users`(`userId`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE SET NULL , FOREIGN KEY(`activeHouseholdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS `index_local_session_userId` ON `local_session` (`userId`);
CREATE INDEX IF NOT EXISTS `index_local_session_householdId` ON `local_session` (`householdId`);
CREATE INDEX IF NOT EXISTS `index_local_session_activeHouseholdId` ON `local_session` (`activeHouseholdId`);
CREATE TABLE IF NOT EXISTS `household_settings` (`householdId` TEXT NOT NULL, `expiryWarningDays` INTEGER NOT NULL DEFAULT 3, PRIMARY KEY(`householdId`), FOREIGN KEY(`householdId`) REFERENCES `households`(`householdId`) ON UPDATE NO ACTION ON DELETE CASCADE );
